"""The recurring presenter: a single, replaceable, procedural pixel-art rig.

Design goals
  * **One identity everywhere.**  The character is *drawn*, never regenerated by
    a model, so head shape, scarf, colours and proportions are bit-identical in
    every scene, format and language.
  * **Pixel-art look.**  The rig draws into a tiny block canvas which is then
    nearest-neighbour upscaled, so edges stay chunky and crisp (reference style)
    and rendering is cheap on a CPU.
  * **Poses, not new art.**  Poses/gestures are parameters (arm angles, lean,
    head tilt, mouth, blink, bounce), so the character can point at a specific
    prop, react to a beat, or hold a board without new assets.
  * **Replaceable.**  `CHARACTER_SPEC` holds all proportions/colours.  Swap the
    spec (or subclass) to install an approved design; nothing else changes.

Original design (not derived from any existing character): "Nami", a presenter
in a cream shirt, indigo overalls, orange scarf and a round dark-teal bob.
"""
from __future__ import annotations

import math
from dataclasses import dataclass, field, replace
from typing import Dict, List, Optional, Sequence, Tuple

from PIL import Image, ImageDraw

BLOCK_W = 26
BLOCK_H = 40
SUBDIV = 4  # canvas pixels per block


@dataclass(frozen=True)
class CharacterSpec:
    outline: Tuple[int, int, int, int] = (26, 20, 34, 255)
    skin: Tuple[int, int, int, int] = (247, 200, 164, 255)
    skin_shade: Tuple[int, int, int, int] = (214, 158, 124, 255)
    hair: Tuple[int, int, int, int] = (36, 56, 70, 255)
    hair_light: Tuple[int, int, int, int] = (54, 84, 100, 255)
    shirt: Tuple[int, int, int, int] = (255, 244, 222, 255)
    shirt_shade: Tuple[int, int, int, int] = (226, 206, 178, 255)
    overalls: Tuple[int, int, int, int] = (58, 86, 148, 255)
    overalls_dark: Tuple[int, int, int, int] = (40, 62, 110, 255)
    accent: Tuple[int, int, int, int] = (255, 138, 76, 255)
    accent_dark: Tuple[int, int, int, int] = (214, 96, 48, 255)
    boots: Tuple[int, int, int, int] = (46, 40, 54, 255)
    eye: Tuple[int, int, int, int] = (30, 28, 40, 255)
    white: Tuple[int, int, int, int] = (255, 255, 255, 255)
    blush: Tuple[int, int, int, int] = (246, 150, 140, 160)


CHARACTER_SPEC = CharacterSpec()

POSES: Dict[str, Dict[str, float]] = {
    # arm angles are degrees: 0 = straight down, 90 = straight out, 180 = up
    "idle": {"arm_l": 8, "arm_r": -6, "elbow_l": 6, "elbow_r": -8, "lean": 0, "head": 0},
    "point_right": {"arm_r": 88, "elbow_r": 6, "arm_l": 6, "elbow_l": 0, "lean": 2, "head": -4},
    "point_left": {"arm_l": -88, "elbow_l": -6, "arm_r": -6, "elbow_r": 0, "lean": -2, "head": 4},
    "present": {"arm_l": 42, "elbow_l": 26, "arm_r": 38, "elbow_r": 22, "lean": 0, "head": 0},
    "explain": {"arm_l": 20, "elbow_l": 44, "arm_r": 70, "elbow_r": 20, "lean": 1, "head": -2},
    "think": {"arm_r": 128, "elbow_r": -34, "arm_l": 6, "elbow_l": 4, "lean": -1, "head": 6},
    "celebrate": {"arm_l": 152, "elbow_l": 18, "arm_r": 148, "elbow_r": -14, "lean": 0, "head": -3},
    "shrug": {"arm_l": 54, "elbow_l": 44, "arm_r": 52, "elbow_r": 40, "lean": 0, "head": 5},
}


def _blk(draw: ImageDraw.ImageDraw, x: float, y: float, w: float, h: float, color, sub: int = SUBDIV) -> None:
    """Draw a rectangle in block coordinates snapped to the canvas grid."""
    x0 = int(round(x * sub))
    y0 = int(round(y * sub))
    x1 = int(round((x + w) * sub))
    y1 = int(round((y + h) * sub))
    if x1 <= x0 or y1 <= y0:
        return
    draw.rectangle((x0, y0, x1 - 1, y1 - 1), fill=color)


def _limb(
    draw: ImageDraw.ImageDraw,
    ox: float,
    oy: float,
    angle_deg: float,
    length: float,
    thickness: float,
    sleeve_color,
    forearm_color,
    outline,
    hand_color=None,
    hand: float = 3.0,
    elbow_deg: float = 0.0,
    bend_at: float = 0.5,
    sleeve_frac: float = 0.55,
    sub: int = SUBDIV,
) -> Tuple[float, float]:
    """Two-segment blocky arm: sleeve, bare forearm, hand. Returns hand pos."""
    a1 = math.radians(angle_deg)
    l1 = length * bend_at
    ex = ox + math.sin(a1) * l1
    ey = oy + math.cos(a1) * l1
    a2 = math.radians(angle_deg + elbow_deg)
    l2 = length - l1
    hx = ex + math.sin(a2) * l2
    hy = ey + math.cos(a2) * l2

    def seg(x0, y0, x1, y1, col, extra=0.0):
        n = max(2, int(math.hypot(x1 - x0, y1 - y0) * 1.6) + 1)
        th = thickness + extra
        for i in range(n + 1):
            t = i / n
            cx = x0 + (x1 - x0) * t
            cy = y0 + (y1 - y0) * t
            _blk(draw, cx - th / 2, cy - th / 2, th, th, col, sub)

    def seg_t(x0, y0, x1, y1, col, t0, t1, extra=0.0):
        n = max(2, int(math.hypot(x1 - x0, y1 - y0) * 1.6) + 1)
        th = thickness + extra
        for i in range(n + 1):
            t = i / n
            if not (t0 <= t <= t1):
                continue
            cx = x0 + (x1 - x0) * t
            cy = y0 + (y1 - y0) * t
            _blk(draw, cx - th / 2, cy - th / 2, th, th, col, sub)

    seg(ox, oy, ex, ey, outline, 1.3)
    seg(ex, ey, hx, hy, outline, 1.3)
    seg_t(ox, oy, ex, ey, sleeve_color, 0.0, 1.0)
    if sleeve_frac < 1.0:
        seg_t(ox, oy, ex, ey, forearm_color, sleeve_frac, 1.0)
        seg(ex, ey, hx, hy, forearm_color)
    else:
        seg(ex, ey, hx, hy, sleeve_color)
    if hand_color is not None:
        _blk(draw, hx - hand / 2 - 0.4, hy - hand / 2 - 0.4, hand + 0.8, hand + 0.8, outline, sub)
        _blk(draw, hx - hand / 2, hy - hand / 2, hand, hand, hand_color, sub)
    return hx, hy


class Character:
    """Draws the presenter at a requested pixel height."""

    def __init__(self, spec: CharacterSpec | None = None) -> None:
        self.spec = spec or CHARACTER_SPEC
        self._cache: Dict[tuple, Image.Image] = {}

    # ------------------------------------------------------------------ canvas
    def sprite(
        self,
        pose: str = "idle",
        *,
        blink: bool = False,
        mouth: str = "smile",
        bounce: float = 0.0,
        tilt: float = 0.0,
        facing: int = 1,
        holding: Optional[str] = None,
        dark: bool = False,
    ) -> Image.Image:
        """Return the block-canvas RGBA sprite for a pose (cached)."""
        key = (pose, blink, mouth, round(bounce, 2), round(tilt, 1), facing, holding, dark)
        cached = self._cache.get(key)
        if cached is not None:
            return cached
        img = self._render(pose, blink, mouth, bounce, tilt, holding, dark)
        if facing < 0:
            img = img.transpose(Image.FLIP_LEFT_RIGHT)
        if len(self._cache) > 400:
            self._cache.clear()
        self._cache[key] = img
        return img

    def _render(self, pose, blink, mouth, bounce, tilt, holding, dark) -> Image.Image:
        """Draw the presenter on the block canvas.

        Vertical layout (blocks, y down):  hair 2.0 · head 4.0-15.0 · torso
        15.0-26.0 · legs 26.0-37.5.  Chunky, readable proportions so the
        character still reads at 260 px tall in a vertical video.
        """
        s = self.spec
        if dark:
            s = replace(
                s,
                shirt=(92, 112, 142, 255), shirt_shade=(72, 90, 118, 255),
                skin=(200, 162, 136, 255), skin_shade=(172, 134, 110, 255),
                overalls=(42, 62, 106, 255), overalls_dark=(30, 46, 82, 255),
                hair=(28, 44, 56, 255),
            )
        W, H = BLOCK_W * SUBDIV, BLOCK_H * SUBDIV
        img = Image.new("RGBA", (W, H), (0, 0, 0, 0))
        d = ImageDraw.Draw(img)
        p = dict(POSES.get(pose, POSES["idle"]))
        cx = BLOCK_W / 2

        lift = max(0.0, bounce)
        head_tilt = p["head"]
        lean = p["lean"] * 0.25

        ground = 37.5
        hip_y = 26.0 - lift
        sh_y = 15.0 - lift
        head_w, head_h = 10.8, 10.6
        head_x = cx - head_w / 2 + lean * 0.6 + (head_tilt * 0.06)
        head_y = 4.0 - lift + head_tilt * 0.04

        # ------------------------------------------------------------------ legs
        for side in (-1, 1):
            lx = cx + side * 2.3 - 1.65 + lean * 0.3
            _blk(d, lx - 0.5, hip_y - 1.0, 4.3, ground - hip_y - 2.2, s.outline)
            _blk(d, lx, hip_y - 0.6, 3.3, ground - hip_y - 2.6, s.overalls_dark)
            bx = lx - 0.9 + side * 0.6
            _blk(d, bx - 0.6, ground - 3.4, 5.2, 3.5, s.outline)
            _blk(d, bx, ground - 3.0, 4.4, 2.6, s.boots)

        # ----------------------------------------------------------------- torso
        torso_w = 11.0
        torso_x = cx - torso_w / 2 + lean
        torso_top = sh_y + 1.0
        torso_h = hip_y - torso_top + 1.6
        _blk(d, torso_x - 0.6, torso_top - 1.2, torso_w + 1.2, torso_h + 1.8, s.outline)
        _blk(d, torso_x, torso_top - 0.8, torso_w, torso_h + 1.0, s.shirt)
        # overalls: full torso from the chest down, so the shirt reads as sleeves
        # and collar only (avoids the white "apron" look)
        _blk(d, torso_x + 0.3, torso_top + 1.4, torso_w - 0.6, torso_h - 0.4, s.overalls)
        _blk(d, torso_x + 0.3, torso_top + 1.4, torso_w - 0.6, 0.8, s.overalls_dark)
        _blk(d, torso_x + 0.3, torso_top + 1.4, torso_w - 0.6, 0.8, s.overalls_dark)
        # straps over the shoulders
        for sx in (torso_x + 1.4, torso_x + torso_w - 3.0):
            _blk(d, sx, torso_top - 2.6, 1.6, 3.4, s.outline)
            _blk(d, sx + 0.3, torso_top - 2.3, 1.0, 2.8, s.overalls)
        # pocket + button dots
        _blk(d, cx - 1.5, torso_top + 3.6, 3.0, 2.4, s.overalls_dark)
        _blk(d, cx - 2.6, torso_top + 1.8, 1.0, 1.0, s.accent)
        _blk(d, cx + 1.6, torso_top + 1.8, 1.0, 1.0, s.accent_dark)
        # shirt collar
        _blk(d, cx - 2.2, torso_top - 1.4, 4.4, 1.4, s.shirt_shade)
        # scarf / neckerchief
        _blk(d, cx - 3.0, torso_top - 1.6, 6.0, 2.6, s.outline)
        _blk(d, cx - 2.5, torso_top - 1.2, 5.0, 1.6, s.accent)
        _blk(d, cx + 1.0, torso_top + 0.2, 1.8, 3.4, s.accent_dark)

        # ------------------------------------------------------------------ head
        # neck
        _blk(d, cx - 1.6, head_y + head_h - 1.0, 3.2, 3.0, s.outline)
        _blk(d, cx - 1.1, head_y + head_h - 0.8, 2.2, 2.6, s.skin_shade)
        # skull
        _blk(d, head_x - 0.5, head_y - 0.6, head_w + 1.0, head_h + 1.0, s.outline)
        _blk(d, head_x, head_y - 0.1, head_w, head_h - 0.1, s.skin)
        # hair: cap + fringe + side locks (never over the eyes)
        _blk(d, head_x - 0.6, head_y - 1.2, head_w + 1.2, 3.6, s.outline)
        _blk(d, head_x - 0.1, head_y - 0.9, head_w + 0.2, 2.9, s.hair)
        _blk(d, head_x + 0.6, head_y + 0.7, head_w - 2.2, 0.8, s.hair_light)
        for fx, fw in ((0.7, 3.2), (4.4, 2.8), (7.7, 3.3)):
            _blk(d, head_x + fx, head_y + 2.1, fw, 1.2, s.hair)
        _blk(d, head_x - 0.7, head_y + 1.8, 1.7, 8.0, s.outline)
        _blk(d, head_x - 0.2, head_y + 2.1, 1.1, 7.4, s.hair)
        _blk(d, head_x + head_w - 1.0, head_y + 1.8, 1.7, 6.6, s.outline)
        _blk(d, head_x + head_w - 0.5, head_y + 2.1, 1.1, 6.0, s.hair)
        # ears
        _blk(d, head_x - 1.4, head_y + 5.4, 1.4, 2.4, s.outline)
        _blk(d, head_x - 1.0, head_y + 5.6, 1.0, 2.0, s.skin_shade)
        _blk(d, head_x + head_w - 0.1, head_y + 5.4, 1.4, 2.4, s.outline)
        _blk(d, head_x + head_w - 0.2, head_y + 5.6, 1.0, 2.0, s.skin_shade)
        # eyes (large, expressive)
        eye_y = head_y + 4.6
        for ex in (head_x + 2.3, head_x + 6.7):
            if blink:
                _blk(d, ex, eye_y + 1.1, 2.6, 0.8, s.eye)
            else:
                _blk(d, ex, eye_y, 2.5, 2.8, s.eye)
                _blk(d, ex + 0.4, eye_y + 0.35, 0.95, 1.0, s.white)
                _blk(d, ex + 1.4, eye_y + 1.65, 0.6, 0.6, s.white)
        # brows
        _blk(d, head_x + 2.0, eye_y - 1.4, 2.7, 0.7, s.hair)
        _blk(d, head_x + 6.5, eye_y - 1.4, 2.7, 0.7, s.hair)
        # blush
        _blk(d, head_x + 0.9, eye_y + 3.1, 2.0, 1.1, s.blush)
        _blk(d, head_x + 7.1, eye_y + 3.1, 2.0, 1.1, s.blush)
        # mouth
        mx = cx - 1.2 + lean * 0.2
        my = eye_y + 4.3
        if mouth == "smile":
            _blk(d, mx, my, 2.6, 0.8, s.outline)
            _blk(d, mx - 0.6, my - 0.7, 0.7, 0.8, s.outline)
            _blk(d, mx + 2.6, my - 0.7, 0.7, 0.8, s.outline)
        elif mouth == "open":
            _blk(d, mx - 0.1, my - 0.4, 2.7, 1.9, s.outline)
            _blk(d, mx + 0.35, my + 0.35, 1.8, 0.8, (140, 58, 68, 255))
            _blk(d, mx + 0.35, my + 1.15, 1.8, 0.3, (238, 238, 238, 255))
        elif mouth == "flat":
            _blk(d, mx, my, 2.6, 0.7, s.outline)
        elif mouth == "o":
            _blk(d, mx + 0.4, my - 0.3, 1.8, 1.9, s.outline)
            _blk(d, mx + 0.9, my + 0.2, 0.8, 0.9, (152, 62, 72, 255))
        else:  # small
            _blk(d, mx + 0.4, my, 1.9, 0.8, s.outline)

        # ------------------------------------------------------------------ arms
        sh_y_arm = sh_y + 2.2
        self._arm(d, s, torso_x - 0.2, sh_y_arm, p["arm_l"], p["elbow_l"], -1, holding)
        self._arm(d, s, torso_x + torso_w + 0.2, sh_y_arm, p["arm_r"], p["elbow_r"], 1, holding)
        return img

    def _arm(self, d, s, x, y, angle, elbow, side, holding, sub=SUBDIV):
        # mirror angles for the left arm so poses read symmetrically
        a = angle * (1 if side > 0 else -1)
        e = elbow * (1 if side > 0 else -1)
        a = max(-170.0, min(170.0, a))
        hx, hy = _limb(
            d, x, y, a, 10.2, 2.9, s.shirt, s.skin, s.outline,
            hand_color=s.skin, hand=3.6, elbow_deg=e, bend_at=0.52,
            sleeve_frac=0.62, sub=sub,
        )
        if holding == "board":
            _blk(d, hx - 2.0, hy - 7.0, 12.0, 8.0, s.outline)
            _blk(d, hx - 1.4, hy - 6.4, 10.8, 6.8, s.white)

    # ------------------------------------------------------------------- draw
    def draw(
        self,
        painter,
        x: float,
        y: float,
        height: float,
        pose: str = "idle",
        *,
        alpha: float = 1.0,
        blink: bool = False,
        mouth: str = "smile",
        bounce: float = 0.0,
        tilt: float = 0.0,
        facing: int = 1,
        holding: Optional[str] = None,
        shadow: bool = True,
        flip_180: bool = False,
    ) -> Tuple[float, float]:
        """Draw the character with its *feet* at (x, y) in layout pixels.

        Returns (drawn_width, drawn_height).
        """
        sprite = self.sprite(pose, blink=blink, mouth=mouth, bounce=bounce, tilt=tilt,
                             facing=facing, holding=holding)
        scale = height / (BLOCK_H * SUBDIV)
        w = sprite.width * scale
        h = sprite.height * scale
        if shadow:
            painter.ellipse(x, y - h * 0.012, w * 0.36, h * 0.022, fill=(0, 0, 0, 90))
        painter.paste_pixel(sprite, x - w / 2, y - h, scale=scale, alpha=alpha)
        return w, h


CHARACTER = Character()


def available_poses() -> List[str]:
    return sorted(POSES)
